def clean_names(names):
    cleaned = []
    for name in names:
        cleaned.append(name.strip())
    return

def lowercase_tags(tags):
    cleaned = []
    for tag in tags:
        cleaned.append(tag.lower())
    return

def titlecase_titles(titles):
    cleaned = []
    for title in titles:
        cleaned.append(title.title())
    return

def normalize_codes(codes):
    cleaned = []
    for code in codes:
        cleaned.append(code.strip())
    return
